import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int ROOM = -1, REAC = -2, BAD_REAC = -3, CAPS = ROOM;

    static class Edge {
        int from, to, rev, flow, cap;
        Edge(int f, int t, int r, int fl, int c) {
            this.from = f;
            this.to = t;
            this.rev = r;
            this.flow = fl;
            this.cap = c;
        }
        int residual() {
            return cap - flow;
        }
    }

    static class MaxFlowSolver {
        int n;
        List<Edge>[] graph;
        Edge[] parent;
        boolean[] visited;

        @SuppressWarnings("unchecked")
        MaxFlowSolver(int size) {
            n = size;
            graph = new ArrayList[n];
            for (int i=0; i<n; i++) {
                graph[i] = new ArrayList<>();
            }
            parent = new Edge[n];
            visited = new boolean[n];
        }

        void reset() {
            for (int i=0; i<n; i++) {
                graph[i].clear();
            }
        }

        void add_edge(int s, int t, int capacity) {
            Edge a = new Edge(s, t, graph[t].size(), 0, capacity);
            Edge b = new Edge(t, s, graph[s].size(), 0, 0);
            graph[s].add(a);
            graph[t].add(b);
        }

        void add_bi_edge(int s, int t, int capacity) {
            Edge a = new Edge(s, t, graph[t].size(), 0, capacity);
            Edge b = new Edge(t, s, graph[s].size(), 0, capacity);
            graph[s].add(a);
            graph[t].add(b);
        }

        boolean find_path(int s, int t) {
            Arrays.fill(parent, null);
            Arrays.fill(visited, false);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = true;
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == t) return true;
                for (Edge e : graph[u]) {
                    if (!visited[e.to] && e.residual() > 0) {
                        parent[e.to] = e;
                        visited[e.to] = true;
                        q.offer(e.to);
                    }
                }
            }
            return false;
        }

        int augment(int s, int t) {
            int flow = Integer.MAX_VALUE;
            int v = t;
            while (v != s) {
                flow = Math.min(flow, parent[v].residual());
                v = parent[v].from;
            }
            v = t;
            while (v != s) {
                parent[v].flow += flow;
                graph[parent[v].to].get(parent[v].rev).flow -= flow;
                v = parent[v].from;
            }
            return flow;
        }

        long max_flow(int s, int t) {
            long total_flow = 0;
            while (find_path(s, t)) {
                total_flow += augment(s, t);
            }
            return total_flow;
        }
    }

    static int[][] station = new int[MAXN][MAXN];
    static int[][] checkpoint = new int[MAXN][MAXN];
    static int[][][] poison = new int[61][MAXN][MAXN];

    static class Coord {
        int x, y, qty;
        Coord(int a, int b, int c) {
            this.x = a;
            this.y = b;
            this.qty = c;
        }
        boolean valid(int N) {
            return (x >= 0 && x < N && y >= 0 && y < N && station[x][y] == ROOM);
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coord)) return false;
            Coord c = (Coord) o;
            return x == c.x && y == c.y;
        }
        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    static List<Coord> evacuees = new ArrayList<>();
    static List<Coord> capsules = new ArrayList<>();
    static int[] deltaX = {-1, 0, 1, 0};
    static int[] deltaY = {0, -1, 0, 1};

    static int translate_char(char ch) {
        if (ch >= '0' && ch <= '9') return ROOM;
        if (ch == 'Y') return REAC;
        if (ch == 'Z') return BAD_REAC;
        return -1;
    }

    static int get_quantity(char ch) {
        return ch - '0';
    }

    static int shortest_path(Coord start, Coord end, int N) {
        boolean[][] visited = new boolean[MAXN][MAXN];
        Queue<Pair<Integer, Coord>> q = new LinkedList<>();
        q.offer(new Pair<>(0, start));
        visited[start.x][start.y] = true;
        while (!q.isEmpty()) {
            Pair<Integer, Coord> front = q.poll();
            int t = front.getKey();
            Coord c = front.getValue();
            if (c.equals(end)) return t;
            if (poison[t][c.x][c.y] != 0) continue;
            for (int i=0; i<4; i++) {
                int nx = c.x + deltaX[i];
                int ny = c.y + deltaY[i];
                Coord n = new Coord(nx, ny, 0);
                if (n.valid(N) && !visited[n.x][n.y]) {
                    if (poison[t][n.x][n.y] == 0) {
                        q.offer(new Pair<>(t + 1, n));
                        visited[n.x][n.y] = true;
                    }
                }
            }
        }
        return 999;
    }

    static void poison_spread(int x, int y, int T, int N) {
        for (int i=0; i<=T; i++) {
            Arrays.fill(poison[i][x], 0);
        }
        poison[0][x][y] = 1;
        for (int t=1; t<=T; t++) {
            for (int i=0; i<N; i++) {
                for (int j=0; j<N; j++) {
                    if (poison[t-1][i][j] != 0) {
                        poison[t][i][j] = 1;
                        for (int move=0; move<4; move++) {
                            int nx = i + deltaX[move], ny = j + deltaY[move];
                            if (nx >= 0 && nx < N && ny >= 0 && ny < N && station[nx][ny] == ROOM) {
                                poison[t][nx][ny] = 1;
                            }
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int T = Integer.parseInt(st.nextToken());

        Coord bad = new Coord(0,0,0);
        for (int i=0; i<N; i++) {
            String line = br.readLine();
            for (int j=0; j<N; j++) {
                char ch = line.charAt(j);
                int val = translate_char(ch);
                station[i][j] = val;
                if (val == ROOM && get_quantity(ch) != 0) {
                    evacuees.add(new Coord(i,j,get_quantity(ch)));
                }
                if (val == BAD_REAC) {
                    bad = new Coord(i,j,0);
                }
            }
        }

        for (int i=0; i<N; i++) {
            String line = br.readLine();
            for (int j=0; j<N; j++) {
                char ch = line.charAt(j);
                int val = translate_char(ch);
                if (val == CAPS && get_quantity(ch) != 0) {
                    capsules.add(new Coord(i,j,get_quantity(ch)));
                    checkpoint[i][j] = get_quantity(ch);
                }
            }
        }

        MaxFlowSolver solver = new MaxFlowSolver(MAXN);
        int sink = MAXN - 1;

        for (int i=0; i<evacuees.size(); i++) {
            solver.add_edge(0, i*2+1, evacuees.get(i).qty);
        }
        for (int i=0; i<capsules.size(); i++) {
            solver.add_bi_edge(i*2+2, sink, capsules.get(i).qty);
        }

        poison_spread(bad.x, bad.y, T, N);

        for (int i=0; i<evacuees.size(); i++) {
            for (int j=0; j<capsules.size(); j++) {
                int t = shortest_path(evacuees.get(i), capsules.get(j), N);
                if (t <= T) {
                    solver.add_bi_edge(i*2+1, j*2+2, 999);
                }
            }
        }

        System.out.println(solver.max_flow(0, sink));
    }

    static class Pair<K,V> {
        private K key;
        private V value;
        Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }
        public K getKey() { return key; }
        public V getValue() { return value; }
    }
}
